        <td>
          <div style="display:flex; gap:6px;">
            <button class="btn btn-primary btn-xs" onclick="Actions.retryJob('${j.id}')">Retry/Re-queue</button>
            <button class="btn btn-error btn-xs" onclick="Actions.discardJob('${j.id}')">Discard</button>
          </div>
        </td>
