      this.audit("REF_DATA_STATE_CHANGED", `${entry.active ? 'Activated' : 'Deactivated'} key ${code} in category ${category}; historical references remain intact.`, "Medium", `${oldState} -> ${entry.active ? 'Active' : 'Inactive'}`);
